import { useState, useEffect } from 'react';
export function useLocalStorage<T>(key: string, initialValue: T) {
  const [value, setValue] = useState<T>(() => {
    const stored = localStorage.getItem(key);
    return stored ? JSON.parse(stored) : initialValue;
  });
  useEffect(() => {
    localStorage.setItem(key, JSON.stringify(value));
  }, [key, value]);
  return [value, setValue] as const;
}

import { useReducer, useEffect } from 'react';

export interface WorkoutSet {
  id: string;
  setNumber: number;
  weight: number;
  reps: number;
  completed: boolean;
}

export interface ActiveExercise {
  exerciseId: string;
  name: string;
  sets: WorkoutSet[];
}

interface WorkoutState {
  workoutName: string;
  exercises: ActiveExercise[];
  startTime: number;
  isPaused: boolean;
}

type WorkoutAction =
  | { type: 'ADD_EXERCISE'; payload: { exerciseId: string; name: string } }
  | { type: 'REMOVE_EXERCISE'; payload: { exerciseId: string } }
  | { type: 'ADD_SET'; payload: { exerciseId: string } }
  | { type: 'UPDATE_SET'; payload: { exerciseId: string; setId: string; weight: number; reps: number; completed: boolean } }
  | { type: 'RESET_WORKOUT' };

const initialState: WorkoutState = {
  workoutName: 'Upper Body Hypertrophy',
  exercises: [],
  startTime: Date.now(),
  isPaused: false,
};

function workoutReducer(state: WorkoutState, action: WorkoutAction): WorkoutState {
  switch (action.type) {
    case 'ADD_EXERCISE':
      if (state.exercises.some((e) => e.exerciseId === action.payload.exerciseId)) return state;
      return {
        ...state,
        exercises: [
          ...state.exercises,
          {
            exerciseId: action.payload.exerciseId,
            name: action.payload.name,
            sets: [{ id: Math.random().toString(), setNumber: 1, weight: 0, reps: 0, completed: false }],
          },
        ],
      };
    case 'REMOVE_EXERCISE':
      return {
        ...state,
        exercises: state.exercises.filter((e) => e.exerciseId !== action.payload.exerciseId),
      };
    case 'ADD_SET':
      return {
        ...state,
        exercises: state.exercises.map((ex) => {
          if (ex.exerciseId !== action.payload.exerciseId) return ex;
          const nextSetNumber = ex.sets.length + 1;
          return {
            ...ex,
            sets: [
              ...ex.sets,
              { id: Math.random().toString(), setNumber: nextSetNumber, weight: 0, reps: 0, completed: false },
            ],
          };
        }),
      };
    case 'UPDATE_SET':
      return {
        ...state,
        exercises: state.exercises.map((ex) => {
          if (ex.exerciseId !== action.payload.exerciseId) return ex;
          return {
            ...ex,
            sets: ex.sets.map((set) =>
              set.id === action.payload.setId
                ? { ...set, weight: action.payload.weight, reps: action.payload.reps, completed: action.payload.completed }
                : set
            ),
          };
        }),
      };
    case 'RESET_WORKOUT':
      return initialState;
    default:
      return state;
  }
}

export function useWorkoutLogger() {
  const [state, dispatch] = useReducer(workoutReducer, initialState, (init) => {
    const saved = localStorage.getItem('active_workout');
    return saved ? JSON.parse(saved) : init;
  });

  useEffect(() => {
    localStorage.setItem('active_workout', JSON.stringify(state));
  }, [state]);

  return { state, dispatch };
}

import React from 'react';

interface DayProgress {
  day: string;
  volumeKg: number;
  targetKg: number;
}

interface WeeklyProgressChartProps {
  data: DayProgress[];
}

export const WeeklyProgressChart: React.FC<WeeklyProgressChartProps> = ({ data }) => {
  const maxVolume = Math.max(...data.map((d) => Math.max(d.volumeKg, d.targetKg)), 1000);

  return (
    <div className="bg-slate-900 border border-slate-800 rounded-2xl p-6 text-slate-100 shadow-xl">
      <div className="flex justify-between items-center mb-6">
        <div>
          <h3 className="text-lg font-bold tracking-tight">Weekly Volume Progress</h3>
          <p className="text-sm text-slate-400">Total lifted weight (kg) per day vs target</p>
        </div>
        <div className="flex items-center gap-4 text-xs font-medium">
          <span className="flex items-center gap-1.5"><span className="w-3 h-3 rounded-full bg-emerald-500 inline-block" /> Actual</span>
          <span className="flex items-center gap-1.5"><span className="w-3 h-3 rounded-full bg-slate-700 inline-block" /> Target</span>
        </div>
      </div>

      <div className="h-56 flex items-end justify-between gap-3 pt-6 border-b border-slate-800">
        {data.map((item, index) => {
          const actualHeight = (item.volumeKg / maxVolume) * 100;
          const targetHeight = (item.targetKg / maxVolume) * 100;

          return (
            <div key={index} className="flex-1 flex flex-col items-center gap-2 h-full justify-end group">
              <div className="w-full flex justify-center items-end gap-1 h-full relative">
                {/* Target Background Bar */}
                <div
                  style={{ height: `${targetHeight}%` }}
                  className="w-3 bg-slate-800 rounded-t-md transition-all duration-300 group-hover:bg-slate-700"
                />
                {/* Actual Lifted Volume Bar */}
                <div
                  style={{ height: `${actualHeight}%` }}
                  className="w-3 bg-gradient-to-t from-emerald-600 to-emerald-400 rounded-t-md transition-all duration-500 shadow-lg shadow-emerald-950/50"
                />
              </div>
              <span className="text-xs font-semibold text-slate-400 group-hover:text-emerald-400 transition-colors">
                {item.day}
              </span>
            </div>
          );
        })}
      </div>
    </div>
  );
};
